package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import androidx.media3.datasource.DataSource;import androidx.media3.exoplayer.drm.DefaultDrmSessionManager;import java.util.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class SoundFlow170Test {
 Context c;ServiceController<WavePlayer> ctrl;
 static Library.Track song(String id)throws Exception{return LibraryUi163Test.song(id,"Track "+id);}
 public static class WavePlayer extends PlaybackService {
  static volatile int batches,sequence;static volatile boolean fail,hold;static CountDownLatch started,gate;volatile int prepares;
  static void reset(){batches=0;sequence=100;fail=hold=false;started=new CountDownLatch(1);gate=new CountDownLatch(1);}
  protected ScApi.Stream playable(Library.Track t){return new ScApi.Stream("https://cf-media.sndcdn.com/synthetic.mp3",false,"",false,180000);}
  protected void prepare(String uri,int ticket,boolean hls,DataSource.Factory factory,DefaultDrmSessionManager drm){prepares++;}
  protected ScApi.Page waveBatch(String owner,Set<String> excluded,BooleanSupplier cancelled)throws Exception{batches++;started.countDown();if(hold)gate.await(4,TimeUnit.SECONDS);if(fail)throw new java.io.IOException("Synthetic offline");ScApi.Page p=new ScApi.Page();for(int n=0;n<30;n++)p.tracks.add(song(""+(sequence++)));return p;}
 }
 @Before public void setup(){c=RuntimeEnvironment.getApplication();WavePlayer.reset();PlaybackService.instance=null;}
 @After public void cleanup(){WavePlayer.gate.countDown();if(ctrl!=null)ctrl.destroy();PlaybackService.instance=null;}
 WavePlayer player(){ctrl=Robolectric.buildService(WavePlayer.class).create();return ctrl.get();}
 Object field(PlaybackService s,String name)throws Exception{Field f=PlaybackService.class.getDeclaredField(name);f.setAccessible(true);return f.get(s);}void set(PlaybackService s,String name,Object value)throws Exception{Field f=PlaybackService.class.getDeclaredField(name);f.setAccessible(true);f.set(s,value);}
 void until(BooleanSupplier done)throws Exception{long end=System.currentTimeMillis()+6000;do{Shadows.shadowOf(Looper.getMainLooper()).idle();if(done.getAsBoolean())return;Thread.sleep(10);}while(System.currentTimeMillis()<end);fail("Timed out");}
 void play(WavePlayer s,int count,boolean wave)throws Exception{Library l=new Library(c);ArrayList<String> ids=new ArrayList<>();for(int i=0;i<count;i++){Library.Track t=song(""+i);l.upsert(t);ids.add(t.uri);}l.save();s.onStartCommand(new Intent("PLAY").putExtra("uri",ids.get(0)).putStringArrayListExtra("queue",ids).putExtra("wave",wave),0,1);until(()->s.prepares>0);}
 @Test public void newIdentityAndForegroundPausedCardAreMediaStyle()throws Exception{assertEquals("com.farika.soundflow",BuildConfig.APPLICATION_ID);WavePlayer s=player();play(s,12,false);s.pause();Notification n=Shadows.shadowOf(c.getSystemService(NotificationManager.class)).getNotification(7);assertEquals(Notification.MediaStyle.class.getName(),n.extras.getString(Notification.EXTRA_TEMPLATE));assertFalse(n.extras.getCharSequence(Notification.EXTRA_TEXT).toString().contains("На паузе ·"));}
 @Test public void destructionDoesNotPublishSeparatePlainCard()throws Exception{WavePlayer s=player();play(s,12,false);s.pause();ctrl.destroy();ctrl=null;assertNull(Shadows.shadowOf(c.getSystemService(NotificationManager.class)).getNotification(7));assertNotNull(PlaybackCheckpoint.read(c));}
 @Test public void waveAutomaticallyAppendsWithoutActivity()throws Exception{WavePlayer s=player();play(s,1,true);until(()->{try{return ((List<?>)field(s,"queue")).size()>1;}catch(Exception e){return false;}});assertEquals(1,WavePlayer.batches);assertTrue(PlaybackCheckpoint.read(c).wave);assertEquals("sc:0",s.current);}
 @Test public void playlistDoesNotFetchWave()throws Exception{WavePlayer s=player();play(s,1,false);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(0,WavePlayer.batches);assertFalse(PlaybackCheckpoint.read(c).wave);}
 @Test public void prefetchStartsOnlyNearEnd()throws Exception{WavePlayer s=player();play(s,12,true);assertEquals(0,WavePlayer.batches);for(int n=0;n<6;n++)s.next();until(()->WavePlayer.batches==1);until(()->{try{return !(Boolean)field(s,"waveBusy");}catch(Exception e){return false;}});assertTrue(((List<?>)field(s,"queue")).size()>12);}
 @Test public void endWaitsForBatchAndAdvancesInsteadOfWrapping()throws Exception{WavePlayer.hold=true;WavePlayer s=player();play(s,1,true);assertTrue(WavePlayer.started.await(4,TimeUnit.SECONDS));s.next();assertTrue((Boolean)field(s,"waveWaiting"));assertEquals("sc:0",s.current);WavePlayer.gate.countDown();until(()->!s.current.equals("sc:0"));assertEquals("sc:100",s.current);}
 @Test public void lateResultCannotChangeNewPlaylist()throws Exception{WavePlayer.hold=true;WavePlayer s=player();play(s,1,true);assertTrue(WavePlayer.started.await(4,TimeUnit.SECONDS));play(s,12,false);WavePlayer.gate.countDown();Thread.sleep(50);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(12,((List<?>)field(s,"queue")).size());assertFalse((Boolean)field(s,"wave"));}
 @Test public void pauseWhileWaitingDoesNotAutoStartNewTrack()throws Exception{WavePlayer.hold=true;WavePlayer s=player();play(s,1,true);assertTrue(WavePlayer.started.await(4,TimeUnit.SECONDS));s.next();s.pause();WavePlayer.gate.countDown();until(()->{try{return !(Boolean)field(s,"waveBusy");}catch(Exception e){return false;}});assertEquals("sc:0",s.current);s.resume();assertEquals("sc:100",s.current);}
 @Test public void networkFailureBacksOffInsteadOfBusyLoop()throws Exception{WavePlayer.fail=true;WavePlayer s=player();play(s,1,true);until(()->{try{return !(Boolean)field(s,"waveBusy");}catch(Exception e){return false;}});s.next();assertEquals(1,WavePlayer.batches);assertTrue((Long)field(s,"waveRetryAfter")>SystemClock.elapsedRealtime());assertTrue(s.notice.contains("волну")||s.notice.contains("соединения"));}
 @Test public void queueWindowDoesNotGrowWithoutBound()throws Exception{WavePlayer s=player();play(s,12,true);for(int turn=0;turn<90;turn++){int old=s.prepares;s.next();until(()->s.prepares>old);until(()->{try{return !(Boolean)field(s,"waveBusy");}catch(Exception e){return false;}});}assertTrue(WavePlayer.batches>=3);assertTrue(((List<?>)field(s,"queue")).size()<=60);assertTrue(((Set<?>)field(s,"waveRecent")).size()<=240);}
 @Test public void recommendationContinuationUsesNextCursorAndExclusions()throws Exception{List<String> calls=new ArrayList<>();ScApi fake=new ScApi(c){public Page likes(String user,String next)throws Exception{Page p=new Page();p.tracks.add(song("1"));return p;}public Page related(String id,String next)throws Exception{calls.add(next);Page p=new Page();p.tracks.add(song(next.isEmpty()?"2":"3"));p.next="https://api-v2.soundcloud.com/tracks/1/related?offset=50";return p;}};RecommendationEngine engine=new RecommendationEngine(c,fake);ScApi.Page first=engine.generate("123","mix",()->false);assertFalse(first.tracks.isEmpty());ScApi.Page second=engine.generate("123","mix",new HashSet<>(Arrays.asList("sc:1","sc:2")),true,()->false);assertEquals(1,second.tracks.size());assertEquals("sc:3",second.tracks.get(0).uri);assertEquals("",calls.get(0));assertTrue(calls.get(1).contains("offset=50"));}
}
